  async function saveReceipt(event){event.preventDefault();if(receiptSaving)return;captureReceipt();const version=sessionVersion,draft=receiptDraft;receiptSaving=true;event.currentTarget.querySelector('[type=submit]').disabled=true;
    try{const response=await api('/orders/'+draft.orderId+'/receipts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(draft)}),result=await response.json();if(version!==sessionVersion)return;
      if(response.status===409&&result.code==='ORDER_CONFLICT'){receiptConflict=result.order;render();return;}if(!response.ok)throw Error(result.error||'Delivery could not be recorded.');
      orders=orders.map(order=>order.id===result.order.id?result.order:order);try{localStorage.removeItem(receiptKey(draft.orderId));}catch{}root.querySelector('[data-receipt-form]')?.remove();receiptDraft=null;receiptConflict=null;message='Delivery recorded. Order managers have been notified.';render();
    }catch(error){if(version===sessionVersion){const node=root.querySelector('[data-receipt-error]');if(node)node.textContent=error.message;}}
    finally{receiptSaving=false;const button=root.querySelector('[data-receipt-form] [type=submit]');if(button)button.disabled=!!receiptConflict;}
  }
  function wireReceipts(){const form=root.querySelector('[data-receipt-form]');if(form){form.onsubmit=saveReceipt;form.addEventListener('input',captureReceipt);form.addEventListener('change',captureReceipt);}root.querySelector('[data-review-receipt]')?.addEventListener('click',()=>{captureReceipt();orders=orders.map(order=>order.id===receiptConflict.id?receiptConflict:order);receiptDraft.expectedUpdatedAt=receiptConflict.updatedAt||receiptConflict.createdAt||'';receiptConflict=null;render();root.querySelector('[data-receipt-form]')?.closest('details')?.setAttribute('open','');});}
  function orderDetails(){
    const order=[...pendingOrders(),...orders].find(order=>order.id===selectedOrderId);
    if(!order)return `<div class="toolbar"><h2>Order unavailable</h2><button data-order-results>${orderReturnView==='order-search'?'Back to search results':'Back to orders'}</button></div><p>Refresh the order list and try again.</p>`;
    const field=(label,value)=>`<div><small>${esc(label)}</small><div style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(value||'Not provided')}</div></div>`;
    const delivery=(date,time)=>date?formatDate(date)+(time?' · '+time:''):'Not confirmed';
    return `<div class="toolbar"><div><h2 style="margin:0">Order #${esc(order.orderNumber)}</h2><small>${esc(order.project)} · ${esc(order.status)}</small></div><button data-order-results>${orderReturnView==='order-search'?'Back to search results':'Back to orders'}</button></div>${message?`<div class="notice">${esc(message)}</div>`:''}<section class="card"><h3>Order information</h3><div class="grid">${field('Order type',order.orderType==='Other'&&order.orderTypeOther?'Other: '+order.orderTypeOther:order.orderType)}${field('Requested by',order.requestedBy||session.username)}${field('Site contact',order.siteContact)}${field('Phone',order.phone)}${field('Requested delivery',delivery(order.requestedDeliveryDate,order.requestedDeliveryTime))}${field('Confirmed delivery',delivery(order.scheduledDeliveryDate,order.scheduledDeliveryTime))}<div class="wide">${field('Location / notes',order.locationNotes)}</div></div>${deliverySummary(order)}<h3>Items (${order.items?.length||0})</h3>${(order.items||[]).map(item=>`<div style="display:flex;gap:16px;padding:12px 0;border-bottom:1px solid #e2e8f0"><strong style="min-width:48px">${esc(item.quantity)} ×</strong><span style="overflow-wrap:anywhere">${esc(item.description)}</span></div>`).join('')}${order.local?`<h3>Files waiting to upload</h3>${(order.attachments||[]).map(file=>`<p>${esc(file.name)}</p>`).join('')||'<p>No files attached.</p>'}<p>This request is saved on this device. It is not fully synced yet.</p>`:orderAttachmentControls(order)}${!order.local?`<div class="actions"><button data-export="pdf" data-order-id="${esc(order.id)}">PDF</button><button data-export="xlsx" data-order-id="${esc(order.id)}">Excel</button></div>`:''}${deliveryReceipts(order)}${orderTimeline(order)}</section>`;
  }

  function attachmentDb(action,files){if(action!=='get'&&!files.length)return Promise.resolve();return new Promise((resolve,reject)=>{const request=indexedDB.open('panelstock-site-order-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onerror=()=>reject(Error('Device storage is unavailable. Your files have not been submitted.'));request.onsuccess=()=>{const db=request.result,tx=db.transaction('files',action==='get'?'readonly':'readwrite'),store=tx.objectStore('files');let value;if(action==='get'){const read=store.get(files);read.onsuccess=()=>{value=read.result;};}else for(const item of files){if(action==='put')store.put(item.file,item.id);else store.delete(item.id);}tx.oncomplete=()=>{db.close();resolve(value);};tx.onerror=tx.onabort=()=>{db.close();reject(Error('Could not save the files on this device.'));};};});}
