  async function queueExistingOrderFiles(event){if(busy)return;const order=orders.find(item=>item.id===event.target.dataset.attachOrder);if(!order)return;const files=Array.from(event.target.files||[]).map(file=>({id:crypto.randomUUID(),name:file.name,size:file.size,file}));if(!files.length)return;const owner=session.username;busy=true;let packet;try{validateOrderFiles(files,order.attachments||[]);if(outbox.queue.length&&outbox.owner!==owner)throw Error('Sync the previous user’s saved requests first.');await attachmentDb('put',files);if(session?.username!==owner)throw Error('Your account changed. Select the files again.');packet={localId:crypto.randomUUID(),idempotencyKey:crypto.randomUUID(),orderId:order.id,order,attachments:files.map(({file,...metadata})=>metadata),createdAt:new Date().toISOString()};outbox.owner=owner;outbox.queue.push(packet);saveOutbox();event.target.value='';message='Files saved on this device, waiting to upload.';}catch(error){if(packet)outbox.queue=outbox.queue.filter(item=>item!==packet);message=error.message;}finally{busy=false;render();}void flush();}
