function openDatePicker(input,trigger){let draft=input.value||dateIso(new Date()),month=new Date(draft+'T00:00:00');month=new Date(month.getFullYear(),month.getMonth(),1);const overlay=document.createElement('div');overlay.className='date-overlay';const draw=()=>{const first=month.getDay(),total=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),previous=new Date(month.getFullYear(),month.getMonth(),0).getDate(),cells=Array.from({length:42},(_,index)=>{const day=index-first+1;return day<1?new Date(month.getFullYear(),month.getMonth()-1,previous+day):day>total?new Date(month.getFullYear(),month.getMonth()+1,day-total):new Date(month.getFullYear(),month.getMonth(),day);}),selected=new Date(draft+'T00:00:00');overlay.innerHTML=`<div class="date-dialog" role="dialog" aria-label="Choose delivery date"><div class="date-selected"><small>SELECT DATE</small><strong>${esc(selected.toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short'}))}</strong></div><div class="date-body"><div class="date-heading"><strong>${esc(month.toLocaleDateString('en-AU',{month:'long',year:'numeric'}))}</strong><span><button type="button" data-prev aria-label="Previous month">‹</button><button type="button" data-next aria-label="Next month">›</button></span></div><div class="date-grid">${['S','M','T','W','T','F','S'].map(day=>`<span>${day}</span>`).join('')}${cells.map(date=>{const value=dateIso(date),outside=date.getMonth()!==month.getMonth();return `<button type="button" data-day="${value}" class="${value===draft?'selected ':''}${value===dateIso(new Date())?'today ':''}${outside?'outside':''}">${date.getDate()}</button>`;}).join('')}</div><div class="date-actions"><button type="button" data-close>CANCEL</button><button type="button" data-ok>OK</button></div></div></div>`;overlay.querySelector('[data-prev]').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);draw();};overlay.querySelector('[data-next]').onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);draw();};overlay.querySelector('[data-close]').onclick=()=>overlay.remove();overlay.querySelector('[data-ok]').onclick=()=>{input.value=draft;trigger.querySelector('span').textContent=formatDate(input.value);captureDraft();overlay.remove();};overlay.querySelectorAll('[data-day]').forEach(button=>button.onclick=()=>{draft=button.dataset.day;draw();});};document.body.appendChild(overlay);draw();}
  const CNC_ICON='<svg class="nav-svg" viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="M6 42V9L10 5H25V13H14V36L10 46Z M39 5H54L58 9V42L54 46L50 36V13H39Z" fill="currentColor"/><rect x="26" y="3" width="12" height="17" rx="1.5" fill="currentColor"/><path d="M27 22H37V26H27Z M29 28H35V32H29Z" fill="currentColor"/><path d="M14 35H50L60 56V60H4V56Z" fill="currentColor"/><path d="M32 33V39" stroke="white" stroke-width="5" stroke-linecap="round"/><path d="M32 33V39" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M24 41V47H34V53H49" stroke="white" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  const SETTINGS_ICON='<svg class="nav-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>';
  const SUPPORT_ICON='<svg class="nav-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 13v-2a8 8 0 0 1 16 0v2"/><path d="M4 12H3a2 2 0 0 0-2 2v2a2 2 0 0 0 2 2h2v-6Z"/><path d="M20 12h1a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2h-2v-6Z"/><path d="M19 18a7 7 0 0 1-5 3"/><circle cx="12.5" cy="21" r="1"/></svg>';
  function read(key,fallback){try{return JSON.parse((key===SESSION_KEY?sessionStorage:localStorage).getItem(key)||'null')||fallback;}catch{return fallback;}}
  function saveOutbox(){localStorage.setItem(OUTBOX_KEY,JSON.stringify(outbox));}
  function readProjects(owner){const saved=read(PROJECTS_KEY,{});return owner&&saved.owner===owner&&Array.isArray(saved.projects)?saved.projects:[];}
  function clearAccountState(){cloudDrafts=[];cloudDraftError='';cloudDiscardId='';captureReceipt();
    captureDraft();orderDraft=null;draftOwner='';selectedOrderFiles=[];selectedOrderId='';discardDraftArmed=false;
    sessionVersion++;session=null;sessionStorage.removeItem(SESSION_KEY);
    orders=[];cncPanels=[];projects=[];supportTickets=[];profile=null;pendingSetup=null;
    supportSelected='';supportPhoto='';supportReplyPhoto='';selectedProfilePhoto=null;
    profileAdjustment={zoom:1,x:50,y:50};profileGesture.pointers.clear();profileGesture.distance=0;
    cncExpanded.clear();view='orders';orderFilter='active';cncFilter='all';cncQuery='';
    localStorage.removeItem(PROJECTS_KEY);
    document.querySelectorAll('.date-overlay').forEach(overlay=>overlay.remove());
    // Keep the outbox and its owner: signing out must never discard unsynced orders.
    receiptDraft=null;receiptConflict=null;receiptSaving=false;orderAlerts=[];statusConflict=null;statusChoices={};statusSaving=false;historyState={};orderReturnView='orders';orderQuery='';orderProject='';orderRequester='';orderDelivery='';
  }
  async function api(path,options={}){
    const version=sessionVersion,token=session?.token||null,headers=new Headers(options.headers||{});
    if(token)headers.set('Authorization','Bearer '+token);
    const current=()=>version===sessionVersion&&token===(session?.token||null);
    const response=await fetch(API+path,{...options,headers,cache:'no-store',signal:options.signal||AbortSignal.timeout(20000)});
    if(!current())throw Error('Session changed. Please sign in again.');
    if(response.status===401&&token){
      clearAccountState();message='Your session expired. Sign in again; saved requests remain on this device.';render();
      throw Error(message);
    }
    // A response arriving or finishing JSON decoding after logout cannot restore old account data.
    const json=response.json.bind(response);
    response.json=async()=>{const data=await json();if(!current())throw Error('Session changed. Please sign in again.');return data;};
    return response;
  }
  async function login(event){event.preventDefault();if(busy)return;busy=true;message='';const form=new FormData(event.currentTarget),remember=form.get('remember');render();try{const response=await api('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:form.get('username'),pin:form.get('pin')})}),result=await response.json();if(!response.ok)throw Error(result.error||'Login failed');if(result.mustChangePin){pendingSetup={username:form.get('username'),pin:form.get('pin'),remember:!!remember};return;}session={token:result.token,username:result.username,isAdmin:result.isAdmin,taskAccess:result.taskAccess||{},expiresAt:result.expiresAt};sessionStorage.setItem(SESSION_KEY,JSON.stringify(session));if(remember)localStorage.setItem(USERNAME_KEY,result.username);else localStorage.removeItem(USERNAME_KEY);await refresh();await flush();}catch(error){message=error.message||'Could not reach the server — check your connection.';}finally{busy=false;render();}}
  async function register(event){event.preventDefault();if(busy)return;busy=true;message='';const form=new FormData(event.currentTarget);if(form.get('newPin')!==form.get('confirmPin')){busy=false;message='The new PINs do not match.';render();return;}try{const response=await api('/set-pin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:pendingSetup.username,oldPin:pendingSetup.pin,newPin:form.get('newPin')})}),result=await response.json();if(!response.ok)throw Error(result.error||'PIN could not be set');session={token:result.token,username:result.username,isAdmin:result.isAdmin,taskAccess:result.taskAccess||{},expiresAt:result.expiresAt};sessionStorage.setItem(SESSION_KEY,JSON.stringify(session));if(pendingSetup.remember)localStorage.setItem(USERNAME_KEY,result.username);pendingSetup=null;await refresh();}catch(error){message=error.message||'Could not reach the server.';}finally{busy=false;render();}}
  const can=task=>session?.isAdmin||session?.taskAccess?.[task]!==false;
  async function refresh(){if(!session)return;const version=sessionVersion;try{const sessionResponse=await api('/session');if(sessionResponse.ok){const current=await sessionResponse.json();session={...session,isAdmin:current.isAdmin,taskAccess:current.taskAccess||{}};sessionStorage.setItem(SESSION_KEY,JSON.stringify(session));}const requests=[can('site.orders.create')?loadCloudDrafts():Promise.resolve(),api('/notifications').then(async response=>{if(response.ok)orderAlerts=((await response.json()).notifications||[]).filter(item=>item.kind==='orders');}),api('/profile').then(async response=>{if(response.ok)profile=(await response.json()).profile;}),api('/support').then(async response=>{if(response.ok)supportTickets=(await response.json()).tickets||[];}),can('site.orders.view')?api('/orders').then(async response=>{if(response.ok){const result=await response.json();orders=result.orders||[];orderTypes=Array.isArray(result.orderTypes)?result.orderTypes:[...DEFAULT_ORDER_TYPES];projects=(result.projectRecords||(result.projects||[]).map(name=>({id:'',name,address:'',notes:'',active:true}))).filter(project=>project.active!==false);localStorage.setItem(PROJECTS_KEY,JSON.stringify({owner:session.username,projects,orderTypes}));}}):Promise.resolve(),can('site.cnc.view')?api('/site/cnc').then(async response=>{if(response.ok)cncPanels=(await response.json()).cncPanels||[];}):Promise.resolve()];await Promise.all(requests);}catch{if(version===sessionVersion)message='Showing saved information. Connect to refresh.';}}
  async function flush(){
    if(busy||!session||!navigator.onLine||!outbox.queue.length||outbox.owner!==session.username)return;
    const owner=session.username,version=sessionVersion;busy=true;render();
    const current=()=>{if(session?.username!==owner||version!==sessionVersion)throw Error('Your account changed. Sign back in to finish uploading.');};
    try{while(outbox.queue.length){current();const packet=outbox.queue[0];
      if(!packet.orderId){const response=await api('/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotencyKey:packet.idempotencyKey,order:packet.order})}),result=await response.json();current();if(!response.ok)throw Error(result.error||'Order submission failed');packet.orderId=result.order.id;saveOutbox();}
      for(const metadata of packet.attachments||[]){const file=await attachmentDb('get',metadata.id);current();if(!file)throw Error('A saved attachment is unavailable on this device. The order has been submitted; add the file again.');const data=await attachmentData(file);current();const response=await api('/orders/'+packet.orderId+'/attachments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:metadata.id,name:metadata.name,data})}),result=await response.json();current();if(!response.ok)throw Error(result.error||'Attachment upload failed. Retry when connected.');}
      if(packet.cloudDraftId){try{await draftApi('/'+packet.cloudDraftId+'/discard',{expectedUpdatedAt:packet.cloudDraftVersion});}catch(error){if(!/not found/i.test(error.message)){retainedDraft=true;}}}
      outbox.queue.shift();try{saveOutbox();}catch(error){outbox.queue.unshift(packet);throw error;}await attachmentDb('delete',packet.attachments||[]);
    }message=retainedDraft?'Order request and attachments submitted. A saved draft was retained; check Drafts.':'Order request and attachments submitted.';await refresh();}catch(error){message=error.message||'Request and files remain saved on this device.';}finally{busy=false;render();}
  }
  function shell(content){return `<main class="shell"><header class="topbar"><div class="brand"><img src="/icon-512.png" alt="Lennox Facades"></div></header><div class="content">${content}</div><nav class="bottom-nav">${can('site.orders.view')?`<button data-orders class="${view==='orders'||view==='order-search'||view==='new'||view==='order'||view==='drafts'?'active':''}"><span class="nav-icon">▤</span><span>Orders</span></button>`:''}${can('site.cnc.view')?`<button data-cnc class="${view==='cnc'?'active':''}"><span class="nav-icon">${CNC_ICON}</span><span>CNC</span></button>`:''}<button data-support class="${view==='support'?'active':''}"><span class="nav-icon">${SUPPORT_ICON}</span><span>Support</span></button><button data-settings class="${view==='settings'?'active':''}"><span class="nav-icon">${SETTINGS_ICON}</span><span>Settings</span></button></nav></main>`;}
  function loginScreen(){const remembered=localStorage.getItem(USERNAME_KEY)||'';root.innerHTML=`<section class="login"><div class="brand"><img src="/icon-512.png" alt="Lennox Facades"><div><h1>Site Orders</h1></div></div><h2 class="login-title"><span class="person">♙</span>${pendingSetup?'Set a new PIN':'Log in to PanelStock'}</h2>${message?`<div class="notice">${esc(message)}</div>`:''}${pendingSetup?`<form data-register><p class="login-help">Your account was created by an administrator. Choose your personal PIN.</p><label>New PIN<input name="newPin" type="password" inputmode="numeric" pattern="[0-9]{6,12}" placeholder="6–12 digits" required></label><label>Confirm new PIN<input name="confirmPin" type="password" inputmode="numeric" pattern="[0-9]{6,12}" placeholder="Re-enter PIN" required></label><button class="primary" type="submit" ${busy?'disabled':''}>${busy?'Saving…':'Set PIN & continue'}</button></form>`:`<form data-login><label>Username<input name="username" autocomplete="username" value="${esc(remembered)}" placeholder="e.g. Sam" required></label><label>PIN<input name="pin" type="password" inputmode="numeric" autocomplete="current-password" placeholder="Your PIN" required></label><label class="remember"><input name="remember" type="checkbox" checked>Remember my username on this device</label><button class="primary" type="submit" ${busy?'disabled':''}>${busy?'Checking…':'Log in'}</button></form>`}</section>`;root.querySelector('[data-login]')?.addEventListener('submit',login);root.querySelector('[data-register]')?.addEventListener('submit',register);}
  function orderList(){const searchMode=view==='order-search',pending=pendingOrders(),all=[...pending,...orders],matches=order=>orderFilter==='active'?(order.local||['submitted','ordered','approved','in_stock'].includes(order.status)):order.status===orderFilter,shown=all.filter(order=>matches(order)&&(!searchMode||matchesOrder(order))),active=all.filter(order=>order.local||['submitted','ordered','approved','in_stock'].includes(order.status)).length,completed=all.filter(order=>order.status==='completed').length,cancelled=all.filter(order=>order.status==='cancelled').length;return `<div class="toolbar site-orders-toolbar"><div><h2 style="margin:0">${searchMode?'Search orders':'Order requests'}</h2><small>${orders.length} order${orders.length===1?'':'s'}${pending.length?` · ${pending.length} waiting to sync`:''}</small></div><div class="actions">${searchMode?'<button data-orders>Back to orders</button>':'<button data-open-order-search>Search orders</button>'}${can('site.orders.create')?`<button data-open-drafts>Drafts (${cloudDrafts.length})</button><button class="primary" data-new-empty>+ New order</button>`:''}</div></div>${message?`<div class="notice ${message.includes('submitted')?'success':''}">${esc(message)}${pending.length?` <button data-retry>${busy?'Syncing…':'Retry'}</button>`:''}</div>`:''}${statusConflictView()}${searchMode?orderSearchControls(all):orderAlertsView()}<div class="order-filters"><button data-order-filter="active" class="${orderFilter==='active'?'active':''}"><span class="filter-label">Active</span><span class="filter-count">${active}</span></button><button data-order-filter="completed" class="${orderFilter==='completed'?'active':''}"><span class="filter-label">Completed</span><span class="filter-count">${completed}</span></button><button data-order-filter="cancelled" class="${orderFilter==='cancelled'?'active':''}"><span class="filter-label">Cancelled</span><span class="filter-count">${cancelled}</span></button></div><p class="site-order-count" role="status">${shown.length} ${searchMode?'matching ':''}order${shown.length===1?'':'s'}</p><section class="card site-order-results">${shown.map(order=>`<article class="order site-order-tile"><div class="site-order-identity"><strong>#${esc(order.orderNumber)} · ${esc(order.project)}</strong><br><small><span class="status">${esc(isPanelOrder(order)||order.local?order.status:orderStatusLabel(order.status))}</span> · ${order.items?.length||0} item${order.items?.length===1?'':'s'} · ${esc(new Date(order.createdAt).toLocaleString('en-AU'))}</small>${orderDates(order)}</div><div class="actions"><button data-order-details="${esc(order.id)}">View order</button>${order.local?'':`<button class="export-button" data-export="pdf" data-order-id="${esc(order.id)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v7H6z"/></svg>PDF</button><button class="export-button" data-export="xlsx" data-order-id="${esc(order.id)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16h16V8zM14 2v6h6M8 12h8M8 16h8"/></svg>Excel</button>`}${can('site.orders.manage')&&!order.local&&!isPanelOrder(order)&&order.status!=='completed'?`<select data-status="${esc(order.id)}" aria-label="Order status" ${statusSaving?'disabled':''}>${['submitted','approved','ordered','in_stock','completed','cancelled'].map(status=>`<option value="${status}" ${(statusChoices[order.id]||order.status)===status?'selected':''}>${orderStatusLabel(status)}</option>`).join('')}</select><button class="primary" data-apply-status="${esc(order.id)}" disabled>Apply</button>`:order.status==='completed'?'<small class="site-order-lock">Completed · Status locked</small>':''}</div></article>`).join('')||`<div class="empty"><strong>${searchMode?'No matching orders':orderFilter==='active'?'You’re all caught up':orderFilter==='completed'?'No completed orders yet':'No cancelled orders'}</strong><p>${searchMode?'Try another search or clear your filters.':orderFilter==='active'?'New requests will appear here while they are in progress.':orderFilter==='completed'?'Orders will appear here when they are completed.':'Cancelled requests will appear here.'}</p>${!searchMode&&orderFilter==='active'&&completed?`<button data-order-filter="completed">View completed orders (${completed})</button>`:''}</div>`}</section>`;}
function newOrder(){const today=dateIso(new Date()),defaults=profile?.siteOrderDefaults||{};return `<div class="toolbar"><h2 style="margin:0">New site order</h2><button data-cancel>Close</button></div><p data-draft-notice role="status">${esc(draftNotice)}</p>${discardDraftArmed?'<div class="notice">Discard this unfinished order and its saved files? <button type="button" data-discard-draft>Yes, discard draft</button><button type="button" data-keep-draft>Keep editing</button></div>':''}${message?`<div class="notice">${esc(message)}</div>`:''}<form class="card site-order-form" data-order><p class="site-required-note"><span class="site-required" aria-hidden="true">*</span> Required to submit. You can save an incomplete draft.</p><section class="site-form-section"><h3>Order details</h3><div class="grid"><label><span>Project <span class="site-required" aria-hidden="true">*</span></span><select name="projectId" required><option value="">Select a project</option>${projects.map(project=>`<option value="${esc(project.id||project.name)}">${esc(project.name)}</option>`).join('')}</select></label><label>Order type<select name="orderType">${[...orderTypes].sort((a,b)=>a.localeCompare(b,'en',{sensitivity:'base'})).map(type=>`<option value="${esc(type)}" ${type==='Panels'?'selected':''}>${esc(type)}</option>`).join('')}</select></label><label class="wide" data-other-type style="display:none">Please specify (optional)<input name="orderTypeOther" maxlength="80" placeholder="e.g. Safety signage"></label></div></section><section class="site-form-section"><h3>Site contact</h3><div class="grid"><label><span>Site contact <span class="site-required" aria-hidden="true">*</span></span><input name="siteContact" maxlength="100" value="${esc(defaults.siteContact||'')}" required></label><label><span>Phone <span class="site-required" aria-hidden="true">*</span></span><input name="phone" type="tel" inputmode="tel" maxlength="40" value="${esc(defaults.phone||'')}" required></label></div></section><section class="site-form-section"><h3>Requested delivery</h3><div class="site-requested-dates"><label><span>Requested delivery date <span class="site-required" aria-hidden="true">*</span></span><input name="requestedDeliveryDate" type="hidden" value="${today}"><button class="date-trigger" data-date-picker type="button"><span>${esc(formatDate(today))}</span><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"></rect><path d="M16 3v4M8 3v4M3 10h18"></path><path d="M8 14h.01M12 14h.01M16 14h.01M8 17h.01M12 17h.01"></path></svg></button></label><label>Requested delivery time<input name="requestedDeliveryTime" type="time"></label></div></section><section class="site-form-section"><h3>Notes</h3><label class="wide">Location / notes<textarea name="locationNotes" maxlength="300" rows="2"></textarea></label></section>${projects.length?'':'<div class="notice">No projects are available yet. Ask an administrator to add one on Web.</div>'}<div class="items"><h3>Items <span class="site-required" aria-hidden="true">*</span></h3><div class="site-item-labels"><span>Qty <span class="site-required" aria-hidden="true">*</span></span><span>Description <span class="site-required" aria-hidden="true">*</span></span></div></div><button data-add type="button" class="site-add-item">Add item</button><section class="order-attachments"><h3>Files and photos</h3><small>Up to 10 files · 5 MB each · 25 MB total</small><div class="order-upload-actions"><label class="order-upload-button order-upload-primary"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/></svg>Choose files<input aria-label="Choose order files" type="file" multiple data-order-files></label><label class="order-upload-button"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 4h-4l-2 3H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-4z"/><circle cx="12" cy="13" r="4"/></svg>Take photo<input aria-label="Take order photo" type="file" accept="image/*" capture="environment" data-order-files></label></div><p data-file-error role="alert"></p><div data-selected-order-files></div></section><div class="actions site-order-submit"><button type="button" data-save-cloud-draft ${busy?'disabled':''}>Save draft</button><button type="button" data-discard-draft>Discard draft</button><button class="primary" type="submit" ${projects.length?'':'disabled'}>Submit request</button></div></form>`;}
  function cncView(){const sorted=[...cncPanels].sort((a,b)=>String(a.jobReference||'').localeCompare(String(b.jobReference||''),'en',{numeric:true})||String(a.orderNumber||'').localeCompare(String(b.orderNumber||''),'en',{numeric:true})||String(a.sheetNumber||'').localeCompare(String(b.sheetNumber||''),'en',{numeric:true})||String(a.panelNumber||'').localeCompare(String(b.panelNumber||''),'en',{numeric:true})),pending=sorted.filter(panel=>panel.status!=='completed').length,completed=sorted.length-pending,q=cncQuery.trim().toLowerCase(),filtered=sorted.filter(panel=>(cncFilter==='all'||(panel.status==='completed'?'completed':'pending')===cncFilter)&&(!q||[panel.orderNumber,panel.jobReference,panel.sheetNumber,panel.panelNumber].join(' ').toLowerCase().includes(q))),jobs=new Map();for(const panel of filtered){const job=panel.jobReference||'No job reference',order=panel.orderNumber||'No order';if(!jobs.has(job))jobs.set(job,new Map());if(!jobs.get(job).has(order))jobs.get(job).set(order,[]);jobs.get(job).get(order).push(panel);}const groups=[...jobs].map(([job,jobOrders])=>{const jobCount=[...jobOrders.values()].reduce((count,rows)=>count+rows.length,0);return `<details class="cnc-job" data-cnc-key="job:${esc(job)}" ${cncExpanded.has('job:'+job)||q?'open':''}><summary><strong>${esc(job)}</strong><span>${jobCount} panel${jobCount===1?'':'s'}</span><b>›</b></summary><div>${[...jobOrders].map(([order,rows])=>{const done=rows.filter(panel=>panel.status==='completed').length,key='order:'+job+'|'+order,sheets=new Set(rows.map(panel=>String(panel.sheetNumber||''))).size;return `<details class="cnc-order" data-cnc-key="${esc(key)}" ${cncExpanded.has(key)||q?'open':''}><summary><span class="cnc-order-icon">▦</span><span class="cnc-order-name"><strong>Order ${esc(order)}</strong><small>${sheets} sheet${sheets===1?'':'s'} · ${rows.length} panel${rows.length===1?'':'s'}</small></span><span class="cnc-progress"><strong>${done}/${rows.length}</strong><small>complete</small></span><b>›</b></summary><div class="cnc-panels">${rows.map(panel=>`<article><div><span>Sheet ${esc(panel.sheetNumber||'—')} · Panel ${esc(panel.panelNumber||'—')}</span><em class="${panel.status==='completed'?'done':''}">${panel.status==='completed'?'Completed':'Pending'}</em></div>${panel.status==='completed'&&panel.completedAt?`<small>Completed ${esc(new Date(panel.completedAt).toLocaleString('en-AU'))}${panel.completedBy?` by ${esc(panel.completedBy)}`:''}</small>`:''}</article>`).join('')}</div></details>`;}).join('')}</div></details>`;}).join('');return `<section class="cnc-tracker"><div class="cnc-heading"><div><h2>CNC Tracker</h2><span>Read-only live view</span></div><button data-refresh>Refresh</button></div>${message?`<div class="notice">${esc(message)}</div>`:''}<label class="cnc-search"><span>⌕</span><input data-cnc-search type="search" value="${esc(cncQuery)}" placeholder="Search order, job, sheet or panel…" aria-label="Search CNC schedule"></label><div class="cnc-pills">${[['all','All',sorted.length],['pending','Pending',pending],['completed','Completed',completed]].map(([value,label,count])=>`<button data-cnc-filter="${value}" class="${cncFilter===value?'active':''}">${label} (${count})</button>`).join('')}</div><div class="cnc-tools"><button data-cnc-expand>Expand all</button><button data-cnc-collapse>Collapse all</button></div><p class="cnc-updated"><i></i>Updated ${new Date().toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})} · refreshes automatically</p><div class="cnc-groups">${groups||`<div class="empty">${sorted.length?'No matching panels.':'No panels scheduled yet.'}</div>`}</div></section>`;}
  function profileEditorOverlay(){if(!selectedProfilePhoto)return'';return `<div class="photo-editor-screen"><header class="photo-editor-head"><button data-cancel-photo type="button">Cancel</button><h2>Adjust photo</h2><button class="primary" data-save-photo type="button">${busy?'Saving…':'Save'}</button></header><main class="photo-editor-stage"><div class="photo-crop-stage" data-photo-gesture><img data-photo-preview src="${esc(selectedProfilePhoto)}" alt="Photo being adjusted" style="object-position:${profileAdjustment.x}% ${profileAdjustment.y}%;transform:scale(${profileAdjustment.zoom})"><span class="photo-crop-guide" aria-hidden="true"></span></div><p class="photo-editor-help">Drag to reposition · Pinch or scroll to zoom</p></main><footer class="photo-editor-foot"><label class="profile-photo-choose">Choose a different photo<input data-profile-photo type="file" accept="image/*"></label></footer></div>`;}
  function orderTypeSettings(){return session?.isAdmin?`<form class="card" data-order-type><h3>Order types</h3><p>${orderTypes.map(esc).join(' · ')}</p><label>New order type<input name="name" maxlength="80" required></label><button class="primary" type="submit" ${busy?'disabled':''}>Add order type</button></form>`:'';}
  async function saveOrderType(event){event.preventDefault();if(!session?.isAdmin||busy)return;const name=new FormData(event.currentTarget).get('name');busy=true;const button=event.currentTarget.querySelector('button');button.disabled=true;try{const response=await api('/order-types',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})}),result=await response.json();if(!response.ok)throw Error(result.error||'Order type could not be added.');orderTypes=result.orderTypes;localStorage.setItem(PROJECTS_KEY,JSON.stringify({owner:session.username,projects,orderTypes}));message='Order type added.';}catch(error){message=error.message;}finally{busy=false;render();}}
  function settingsView(){const current=profile||{displayName:session.username,email:'',profilePhoto:''},shown=current.profilePhoto;return `<div class="toolbar"><div><h2 style="margin:0">Settings</h2><small>Account and Site app preferences</small></div></div>${message?`<div class="notice ${message.includes('saved')?'success':''}">${esc(message)}</div>`:''}<div class="card account-summary"><div class="account-person"><div class="account-avatar">${shown?`<img src="${esc(shown)}" alt="">`:`<span>${esc((current.displayName||session.username||'?').slice(0,2).toUpperCase())}</span>`}</div><div><strong>Signed in as</strong><span>${esc(current.displayName||session.username)}${session.isAdmin?' · Admin':''}</span></div></div></div><form class="card" data-profile><div class="grid"><label>Display name<input name="displayName" maxlength="100" value="${esc(current.displayName||session.username)}" required></label><label>Email<input name="email" type="email" maxlength="160" value="${esc(current.email||'')}"></label><div class="wide"><h3>Site order defaults</h3><small>These details fill in new orders automatically. You can change them for each order.</small></div><label>Site contact<input name="defaultSiteContact" autocomplete="name" maxlength="100" value="${esc(current.siteOrderDefaults?.siteContact||'')}" placeholder="Contact name for your orders"></label><label>Site contact phone number<input name="defaultSitePhone" type="tel" inputmode="tel" autocomplete="tel" maxlength="40" value="${esc(current.siteOrderDefaults?.phone||'')}" placeholder="e.g. 0400 000 000"></label><div class="wide profile-photo-editor"><strong>Profile photo</strong><div class="profile-photo-preview">${shown?`<img src="${esc(shown)}" alt="Your profile">`:`<span>${esc((current.displayName||session.username||'?').slice(0,2).toUpperCase())}</span>`}</div><div class="profile-photo-actions"><label class="profile-photo-choose photo-camera"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 4h-4l-2 3H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-4z"/><circle cx="12" cy="13" r="4"/></svg>Take photo<input data-profile-photo type="file" accept="image/*" capture="user" aria-label="Take profile photo"></label><label class="profile-photo-choose photo-library"><svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/></svg>Choose photo<input data-profile-photo name="profilePhoto" type="file" accept="image/*" aria-label="Choose profile photo"></label></div>${current.profilePhoto?'<button data-adjust-current type="button">Adjust current photo</button>':''}<small>Take a new photo or choose one from your library. You can adjust it before saving.</small>${current.profilePhoto?'<button class="danger-button" data-remove-photo type="button">Remove photo</button>':''}</div></div><div class="actions settings-actions"><button class="primary" type="submit">Save profile</button><button data-logout type="button">Log out</button></div></form>${orderTypeSettings()}${profileEditorOverlay()}`;}
  function supportView(){
    const selected=supportTickets.find(ticket=>ticket.id===supportSelected);
    if(selected){
      const replies=(selected.messages||[]).map(reply=>`<article class="order"><div><strong>${esc(reply.isAdmin?'Support · '+reply.author:reply.author)}</strong><p>${esc(reply.body)}</p>${reply.photo?`<img src="${esc(reply.photo)}" alt="Reply attachment" style="max-width:100%;max-height:240px;border-radius:10px">`:''}<small>${esc(new Date(reply.createdAt).toLocaleString('en-AU'))}</small></div></article>`).join('');
      const statusControl=session.isAdmin?'<select data-support-status><option>Open</option><option>In Progress</option><option>Resolved</option></select>':`<span class="status">${esc(selected.status)}</span>`;
      return `<div class="toolbar"><button data-support-back>← Tickets</button><div><h2 style="margin:0">${esc(selected.subject)}</h2><small>${esc(selected.category)} · ${esc(selected.priority)} priority</small></div></div>${message?`<div class="notice">${esc(message)}</div>`:''}<section class="card"><div class="actions">${statusControl}</div><p>${esc(selected.description)}</p>${selected.photo?`<img src="${esc(selected.photo)}" alt="Ticket attachment" style="max-width:100%;max-height:320px;border-radius:12px">`:''}<div>${replies}</div><form data-support-reply><label>Reply<textarea name="message" rows="4" placeholder="Write a reply…"></textarea></label><label class="profile-photo-choose">Add photo<input data-support-reply-photo type="file" accept="image/*"></label>${supportReplyPhoto?`<img src="${esc(supportReplyPhoto)}" alt="Attachment preview" style="height:80px;border-radius:10px">`:''}<button class="primary" type="submit" ${busy?'disabled':''}>${busy?'Sending…':'Send reply'}</button></form></section>`;
    }
    const rows=supportTickets.map(ticket=>`<button data-support-ticket="${esc(ticket.id)}" style="width:100%;margin-top:8px;text-align:left"><strong>${esc(ticket.subject)}</strong><br><small>${session.isAdmin?esc(ticket.createdBy)+' · ':''}${esc(ticket.status)} · ${esc(new Date(ticket.updatedAt).toLocaleDateString('en-AU'))}</small></button>`).join('');
    return `<div class="toolbar"><div style="display:flex;align-items:center;gap:12px"><span style="width:48px;height:48px;display:grid;place-items:center;border-radius:12px;background:#0f172a;color:#fff">${SUPPORT_ICON}</span><div><h2 style="margin:0">Support</h2><small>${session.isAdmin?'View and respond to user tickets':'Ask for help and track your requests'}</small></div></div></div>${message?`<div class="notice">${esc(message)}</div>`:''}<form class="card" data-support-create><label>Subject<input name="subject" maxlength="140" required></label><div class="grid"><label>Category<select name="category"><option>General</option><option>Technical issue</option><option>Account access</option><option>Feature request</option></select></label><label>Priority<select name="priority"><option>Low</option><option selected>Normal</option><option>High</option><option>Urgent</option></select></label></div><label>Description<textarea name="description" rows="5" maxlength="5000" required></textarea></label><label class="profile-photo-choose">Add photo<input data-support-photo type="file" accept="image/*"></label>${supportPhoto?`<img src="${esc(supportPhoto)}" alt="Attachment preview" style="height:80px;border-radius:10px">`:''}<button class="primary" type="submit" ${busy?'disabled':''}>${busy?'Submitting…':'Submit ticket'}</button></form><section class="card"><h3>${session.isAdmin?'All tickets':'My tickets'}</h3>${rows||'<p>No support tickets yet.</p>'}</section>`;
  }
  function updateItemRequirements(){
    const rows=[...root.querySelectorAll('.item')];
    rows.forEach(row=>{
      const quantity=row.querySelector('[name=quantity]'),description=row.querySelector('[name=description]');
      // Rows without descriptions are omitted when submitting, wherever they appear.
      const hasDescription=!!description.value.trim();
      description.required=false;
      quantity.required=hasDescription;
      quantity.min=hasDescription?'1':'';
      quantity.step=hasDescription?'1':'any';
    });
  }
  function addItem(focus=false){
    const list=root.querySelector('.items'),row=document.createElement('div');
    row.className='item';
    row.innerHTML='<input name="quantity" type="number" min="1" step="1" value="1" required enterkeyhint="next" aria-label="Quantity"><input name="description" maxlength="180" enterkeyhint="enter" placeholder="Item description" aria-label="Description"><button type="button" aria-label="Remove item">×</button>';
    row.querySelector('button').onclick=()=>{row.remove();updateItemRequirements();captureDraft();};
    row.addEventListener('input',updateItemRequirements);
    row.addEventListener('keydown',event=>{
      if(event.key!=='Enter'||event.isComposing||event.keyCode===229||!event.target.matches('input'))return;
      event.preventDefault();
      if(event.repeat)return;
      const quantity=row.querySelector('[name=quantity]'),description=row.querySelector('[name=description]');
      if(!quantity.reportValidity()){quantity.focus();return;}
      if(!description.value.trim()){description.focus();return;}
      if(!description.reportValidity()){description.focus();return;}
      if(row.nextElementSibling?.classList.contains('item'))row.nextElementSibling.querySelector('[name=description]').focus();
      else addItem(true);
    });
    list.appendChild(row);updateItemRequirements();
    if(focus===true){row.querySelector('[name=description]').focus();captureDraft();}
    return row;
  }
  async function submitOrder(event){event.preventDefault();if(busy)return;captureDraft();if(selectedOrderFiles.some(file=>file.missing)){root.querySelector('[data-file-error]').textContent='Remove unavailable files and attach them again before submitting.';return;}const form=new FormData(event.currentTarget),selected=projects.find(project=>(project.id||project.name)===form.get('projectId')),items=[...root.querySelectorAll('.item')].map(row=>({quantity:Number(row.querySelector('[name=quantity]').value),description:row.querySelector('[name=description]').value.trim()})).filter(item=>item.quantity>0&&item.description);if(!items.length){message='Add at least one item.';render();return;}if(outbox.queue.length&&outbox.owner!==session.username){message=`Saved requests on this device belong to ${outbox.owner}.`;view='orders';render();return;}if(!selected){message='Choose an available project before submitting.';render();return;}const order={projectId:selected?.id||null,project:selected?.name||form.get('projectId'),orderType:form.get('orderType'),orderTypeOther:form.get('orderType')==='Other'?(form.get('orderTypeOther')||''):'',siteContact:form.get('siteContact'),phone:form.get('phone'),requestedDeliveryDate:form.get('requestedDeliveryDate'),requestedDeliveryTime:form.get('requestedDeliveryTime'),locationNotes:form.get('locationNotes'),items};const owner=session.username;busy=true;let packet;try{validateOrderFiles(selectedOrderFiles);await attachmentDb('put',selectedOrderFiles);if(session?.username!==owner)throw Error('Your account changed. Submit the order again.');packet={localId:crypto.randomUUID(),idempotencyKey:orderDraft?.id||crypto.randomUUID(),cloudDraftId:orderDraft?.cloudUpdatedAt?orderDraft.id:null,cloudDraftVersion:orderDraft?.cloudUpdatedAt||'',order,attachments:selectedOrderFiles.map(({file,...metadata})=>metadata),createdAt:new Date().toISOString()};outbox.owner=owner;outbox.queue.push(packet);saveOutbox();try{localStorage.removeItem(DRAFT_KEY+owner);}catch{}orderDraft=null;draftOwner='';selectedOrderFiles=[];}catch(error){if(packet)outbox.queue=outbox.queue.filter(item=>item!==packet);root.querySelector('[data-file-error]').textContent=error.message;return;}finally{busy=false;}view='orders';message=navigator.onLine?'Submitting request…':'Request saved on this device and will submit when connected.';render();void flush();}
  async function downloadOrder(button){const format=button.dataset.export,id=button.dataset.orderId,original=button.innerHTML,preview=format==='pdf'?window.open('about:blank','_blank'):null;button.disabled=true;button.textContent='Preparing…';if(preview)preview.opener=null;const ticket=async()=>{const response=await api('/orders/'+id+'/pdf-link',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),result=await response.json();if(!response.ok||!result.pdfToken)throw Error(result.error||'Order file could not be generated');return result.pdfToken;};try{if(format==='pdf'){const [previewToken,downloadToken]=await Promise.all([ticket(),ticket()]),base=API+'/orders/'+id+'/pdf';if(preview)preview.location.replace(base+'?ticket='+encodeURIComponent(previewToken));const link=document.createElement('a');link.href=base+'?download=1&ticket='+encodeURIComponent(downloadToken);link.style.display='none';document.body.appendChild(link);link.click();link.remove();if(!preview)message='The PDF download started, but your browser blocked the preview tab.';}else{const fileToken=await ticket();window.location.assign(API+'/orders/'+id+'/'+format+'?ticket='+encodeURIComponent(fileToken));}}catch(error){if(preview&&!preview.closed)preview.close();message=error.message;render();}finally{if(button.isConnected){button.disabled=false;button.innerHTML=original;}}}
  const readPhoto=file=>new Promise((resolve,reject)=>{if(!file.type.startsWith('image/')){reject(Error('Choose an image from your photo library.'));return;}const reader=new FileReader();reader.onerror=()=>reject(Error('Photo could not be read.'));reader.onload=()=>{const source=String(reader.result||'');if(file.size<=1000000){resolve(source);return;}const image=new Image();image.onerror=()=>reject(Error('This photo format could not be opened. Try JPEG, PNG or WebP.'));image.onload=()=>{let limit=1024;while(limit>=400){const scale=Math.min(1,limit/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);for(let quality=.88;quality>=.48;quality-=.1){const result=canvas.toDataURL('image/jpeg',quality);if(result.length<=1450000){resolve(result);return;}}limit=Math.floor(limit*.75);}reject(Error('This photo could not be reduced enough. Please choose another photo.'));};image.src=source;};reader.readAsDataURL(file);});
  const cropProfilePhoto=(source,{zoom,x,y})=>new Promise((resolve,reject)=>{const image=new Image();image.onerror=()=>reject(Error('Profile photo could not be adjusted.'));image.onload=()=>{const size=512,scale=Math.max(size/image.naturalWidth,size/image.naturalHeight)*zoom,sourceWidth=size/scale,sourceHeight=size/scale,maxX=Math.max(0,image.naturalWidth-sourceWidth),maxY=Math.max(0,image.naturalHeight-sourceHeight),canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;canvas.getContext('2d').drawImage(image,maxX*x/100,maxY*y/100,sourceWidth,sourceHeight,0,0,size,size);for(let quality=.9;quality>=.5;quality-=.1){const result=canvas.toDataURL('image/jpeg',quality);if(result.length<=1450000){resolve(result);return;}}reject(Error('Profile photo could not be reduced enough.'));};image.src=source;});
  async function saveProfile(event){event.preventDefault();busy=true;message='';const form=new FormData(event.currentTarget);try{const payload={displayName:form.get('displayName'),email:form.get('email'),siteOrderDefaults:{siteContact:form.get('defaultSiteContact')||'',phone:form.get('defaultSitePhone')||''}};if(selectedProfilePhoto)payload.profilePhoto=await cropProfilePhoto(selectedProfilePhoto,profileAdjustment);const response=await api('/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok)throw Error(result.error||'Profile could not be saved.');profile=result.profile;selectedProfilePhoto=null;profileAdjustment={zoom:1,x:50,y:50};message='Profile saved.';}catch(error){message=error.message||'Could not reach the server.';}finally{busy=false;render();}}
  function wireProfilePhoto(){root.addEventListener('change',async event=>{if(!event.target.matches('[data-profile-photo]'))return;const file=event.target.files?.[0];if(!file)return;message='Preparing photo…';try{selectedProfilePhoto=await readPhoto(file);profileAdjustment={zoom:1,x:50,y:50};message='';}catch(error){message=error.message||'Profile photo could not be prepared.';}render();});root.addEventListener('input',event=>{if(!event.target.matches('[data-photo-adjust]'))return;profileAdjustment[event.target.dataset.photoAdjust]=Number(event.target.value);const image=root.querySelector('[data-photo-preview]');if(image){image.style.objectPosition=`${profileAdjustment.x}% ${profileAdjustment.y}%`;image.style.transform=`scale(${profileAdjustment.zoom})`;}});root.addEventListener('click',event=>{if(!event.target.closest('[data-cancel-photo]'))return;selectedProfilePhoto=null;profileAdjustment={zoom:1,x:50,y:50};message='';render();});}
